'use strict';

// MODULES //

var erfinv = require( '@stdlib/math/base/special/erfinv' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );


// MAIN //

/**
* Evaluates the quantile function for a half-normal distribution with scale parameter `sigma` at a probability `p`.
*
* @param {Probability} p - input probability
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} evaluated quantile function
*
* @example
* var y = quantile( 0.5, 1.0 );
* // returns 0.6744897501960817
*
* @example
* var y = quantile( 0.9, 2.0 );
* // returns 3.289707253902946
*
* @example
* var y = quantile( 0.0, 1.0 );
* // returns 0.0
*
* @example
* var y = quantile( NaN, 1.0 );
* // returns NaN
*
* @example
* var y = quantile( 0.5, NaN );
* // returns NaN
*
* @example
* // Negative scale parameter:
* var y = quantile( 0.5, -1.0 );
* // returns NaN
*
* @example
* // Invalid probability:
* var y = quantile( 1.5, 1.0 );
* // returns NaN
*/
function quantile( p, sigma ) {
	if (
		isnan( p ) ||
		isnan( sigma ) ||
		sigma < 0.0 ||
		p < 0.0 ||
		p > 1.0
	) {
		return NaN;
	}
	if ( sigma === 0.0 ) {
		return 0.0;
	}
	if ( p === 0.0 ) {
		return 0.0;
	}
	if ( p === 1.0 ) {
		return Infinity;
	}
	return sigma * sqrt( 2.0 ) * erfinv( p );
}


// EXPORTS //

module.exports = quantile;
